import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import NotificationBell from './NotificationBell';
import { 
  Home, 
  User, 
  Briefcase, 
  Trophy, 
  Users, 
  LogOut, 
  Menu, 
  X,
  GraduationCap,
  MessageCircle,
  Star,
  Award,
  BarChart3,
  Sparkles,
  Zap
} from 'lucide-react';

const Navbar = () => {
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navigation = [
    { name: 'Dashboard', href: '/dashboard', icon: Home },
    { name: 'Jobs', href: '/jobs', icon: Briefcase },
    { name: 'Competitions', href: '/competitions', icon: Trophy },
    ...(user?.role !== 'student' ? [{ name: 'Students', href: '/students', icon: Users }] : []),
    { name: 'Chat', href: '/chat', icon: MessageCircle },
    ...(user?.role === 'student' ? [
      { name: 'Recommendations', href: '/recommendations', icon: Star },
      { name: 'Leaderboard', href: '/leaderboard', icon: Award }
    ] : []),
    ...(user?.role !== 'student' ? [{ name: 'Analytics', href: '/analytics', icon: BarChart3 }] : []),
    { name: 'Profile', href: '/profile', icon: User },
  ];

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="bg-white/95 backdrop-blur-md shadow-2xl border-b-0 sticky top-0 z-50">
      <div className="absolute inset-0 bg-gradient-to-r from-blue-600/5 via-purple-600/5 to-indigo-600/5"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <div className="flex justify-between h-18">
          {/* Logo and Brand */}
          <div className="flex items-center">
            <Link to="/dashboard" className="flex items-center space-x-3 group">
              <div className="relative">
                <div className="bg-gradient-to-r from-blue-600 to-purple-600 p-3 rounded-xl shadow-lg group-hover:shadow-xl transition-all duration-300 group-hover:scale-110">
                  <GraduationCap className="h-7 w-7 text-white" />
                </div>
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-gradient-to-r from-yellow-400 to-orange-500 rounded-full animate-pulse">
                  <Sparkles className="h-3 w-3 text-white p-0.5" />
                </div>
              </div>
              <div className="hidden sm:block">
                <h1 className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent group-hover:from-purple-600 group-hover:to-blue-600 transition-all duration-300">
                  Talent Hub
                </h1>
                <p className="text-sm text-gray-600 font-medium">🎓 Centurion University</p>
              </div>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-2">
            {navigation.map((item) => {
              const Icon = item.icon;
              return (
                <Link
                  key={item.name}
                  to={item.href}
                  className={`relative flex items-center space-x-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all duration-300 transform hover:scale-105 group ${
                    isActive(item.href)
                      ? 'bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-lg'
                      : 'text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-blue-500 hover:to-purple-600 hover:shadow-lg'
                  }`}
                >
                  <Icon className={`h-5 w-5 transition-transform duration-300 ${
                    isActive(item.href) ? 'animate-pulse' : 'group-hover:rotate-12'
                  }`} />
                  <span>{item.name}</span>
                  {isActive(item.href) && (
                    <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-yellow-400 rounded-full animate-bounce"></div>
                  )}
                </Link>
              );
            })}
          </div>

          {/* User Menu */}
          <div className="flex items-center space-x-4">
            {/* Notification Bell for Students */}
            <div className="transform hover:scale-110 transition-transform duration-300">
              <NotificationBell />
            </div>

            <div className="hidden md:block text-right bg-gradient-to-r from-blue-50 to-purple-50 px-4 py-2 rounded-xl">
              <p className="text-sm font-bold text-gray-900 flex items-center space-x-1">
                <span>{user?.name}</span>
                <Zap className="h-4 w-4 text-yellow-500" />
              </p>
              <p className="text-xs font-medium text-blue-600 capitalize">{user?.role}</p>
            </div>
            <button
              onClick={handleLogout}
              className="flex items-center space-x-2 px-4 py-2.5 rounded-xl text-sm font-semibold text-gray-600 hover:text-white hover:bg-gradient-to-r hover:from-red-500 hover:to-pink-600 transition-all duration-300 transform hover:scale-105 hover:shadow-lg group"
            >
              <LogOut className="h-5 w-5 group-hover:rotate-12 transition-transform duration-300" />
              <span className="hidden sm:block">Logout</span>
            </button>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="inline-flex items-center justify-center p-3 rounded-xl bg-gradient-to-r from-blue-500 to-purple-600 text-white hover:from-purple-600 hover:to-blue-500 transition-all duration-300 transform hover:scale-110 shadow-lg"
              >
                {isMobileMenuOpen ? (
                  <X className="h-6 w-6 rotate-90 transition-transform duration-300" />
                ) : (
                  <Menu className="h-6 w-6 transition-transform duration-300" />
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden animate-fade-in">
          <div className="px-4 pt-4 pb-6 space-y-3 bg-gradient-to-br from-blue-50 via-purple-50 to-indigo-50 backdrop-blur-md border-t border-white/20">
            <div className="bg-white/80 backdrop-blur-sm px-4 py-3 rounded-xl border border-white/20 mb-4">
              <p className="text-lg font-bold text-gray-900 flex items-center space-x-2">
                <span>{user?.name}</span>
                <Sparkles className="h-5 w-5 text-yellow-500" />
              </p>
              <p className="text-sm font-medium text-blue-600 capitalize">{user?.role}</p>
            </div>
            {navigation.map((item) => {
              const Icon = item.icon;
              return (
                <Link
                  key={item.name}
                  to={item.href}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center space-x-3 px-4 py-3 rounded-xl text-base font-semibold transition-all duration-300 transform hover:scale-105 ${
                    isActive(item.href)
                      ? 'bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-lg'
                      : 'text-gray-700 hover:text-white hover:bg-gradient-to-r hover:from-blue-500 hover:to-purple-600 bg-white/60 hover:shadow-lg'
                  }`}
                >
                  <Icon className={`h-6 w-6 ${
                    isActive(item.href) ? 'animate-pulse' : ''
                  }`} />
                  <span>{item.name}</span>
                </Link>
              );
            })}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
